package dev.hexora.config;
import org.springframework.context.annotation.*; import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.SecurityFilterChain; import org.springframework.security.authentication.AuthenticationManager; import org.springframework.security.config.annotation.authentication.configuration.AuthenticationConfiguration;
@Configuration @EnableWebSecurity @EnableMethodSecurity
public class SecurityConfig {
 @Bean AuthenticationManager authenticationManager(AuthenticationConfiguration c)throws Exception{return c.getAuthenticationManager();}
 @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder(12);}
 @Bean SecurityFilterChain security(HttpSecurity http)throws Exception { return http.csrf(c->c.ignoringRequestMatchers("/api/contact","/api/auth/login","/api/auth/register")).authorizeHttpRequests(a->a.requestMatchers("/","/login","/register","/home","/css/**","/js/**","/images/**","/webjars/**","/api/auth/login","/api/auth/register","/api/contact","/api/profile/public/**","/api/projects/public/**","/api/skills/public/**","/api/services/public/**","/api/experience/public/**","/api/statistics/public/**","/api/media/public/**","/actuator/health").permitAll().requestMatchers("/dashboard","/profile","/api/**").authenticated().anyRequest().permitAll()).formLogin(f->f.disable()).httpBasic(b->b.disable()).logout(l->l.logoutUrl("/api/auth/logout").logoutSuccessHandler((req,res,auth)->{res.setStatus(204);})).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.IF_REQUIRED)).build(); }
}
